def gen(rng):
    def fmt(ids, k):
        return f"{len(ids)} {k}\n" + ' '.join(map(str, ids))
    tests = [fmt([1], 1), fmt([5, 5, 5], 2), fmt([8, 4, 2, 1], 4), fmt([1000000000, 536870912, 1], 2),
             fmt([2**29 + 1, 2**29 + 2**28 + 1, 17], 3)]
    for n in (2, 3, 5, 8, 12):
        for _ in range(3):
            ids = [rng.randint(1, 300) for _ in range(n)]
            tests.append(fmt(ids, rng.randint(1, n)))
    ids = [rng.randint(1, 10**9) for _ in range(100000)]
    tests.append(fmt(ids, 50000))
    ids = [rng.randint(1, 255) for _ in range(100000)]
    tests.append(fmt(ids, 100000))
    ids = [rng.choice([2**i + 1 for i in range(1, 29)] + [2**i for i in range(30)]) for _ in range(100000)]
    tests.append(fmt(ids, 7))
